  const { candidates, ballots } = election
  const continuing = new Set(candidates)
  const rounds = []

  while (true) {
    const voteCount = {}
    let exhausted = 0

    // Initialize vote counts for all continuing candidates
    for (const candidate of continuing) {
      voteCount[candidate] = 0
    }

    // Count votes in this round
    for (const ballot of ballots) {
      let voted = false
      for (const candidate of ballot.ranked) {
        if (continuing.has(candidate)) {
          voteCount[candidate] += ballot.count
          voted = true
          break
        }
      }
      if (!voted) {
        exhausted += ballot.count
      }
    }

    const activeTotal = Object.values(voteCount).reduce((a, b) => a + b, 0)

    rounds.push({
      voteCount: { ...voteCount },
      exhausted,
      activeTotal,
      candidates: Array.from(continuing),
      eliminated: null
    })

    // Check for winner
    for (const candidate of continuing) {
      if (voteCount[candidate] * 2 > activeTotal) {
        return { rounds, winner: candidate }
      }
    }

    // Check if election is over (no active votes)
    if (activeTotal === 0) {
      return { rounds, winner: null }
    }

    // Find candidate to eliminate
    const toEliminate = findCandidateToEliminate(continuing, rounds)
    continuing.delete(toEliminate)
    rounds[rounds.length - 1].eliminated = toEliminate
  }
}

