  const candidates = Array.from(continuing)

  // Find candidates with fewest votes in current round
  const currentRound = rounds[rounds.length - 1]
  let minVotes = Infinity
  for (const candidate of candidates) {
    const votes = currentRound.voteCount[candidate]
    if (votes < minVotes) {
      minVotes = votes
    }
